class Depends:
    dependency: Optional[Callable] = None
    use_cache: bool = True

    def __hash__(self):
        return hash((self.dependency, self.use_cache))

@dataclass
class Security(Depends):
    scopes: Optional[Sequence[str]] = None
    def __hash__(self):
        return hash((self.dependency, self.use_cache, tuple(self.scopes) if self.scopes is not None else None))

